const inputItems = $input.all();
const outputItems = [];

// Get the response from a typical n8n AI node.
function getPayload(item) {
    const data = item.json ?? {};

    if (data && typeof data === "object" && !Array.isArray(data)) {
        for (const key of ["output", "text", "response", "content", "result"]) {
            if (data[key] !== undefined && data[key] !== null) {
                return data[key];
            }
        }

        if (
            data.message &&
            typeof data.message === "object" &&
            data.message.content !== undefined
        ) {
            return data.message.content;
        }
    }

    // Also supports records already parsed as JSON.
    return data;
}

// Extract JSON objects or arrays from text containing extra content.
function extractJSONChunks(text) {
    const chunks = [];
    let start = -1;
    let depth = 0;
    let inString = false;
    let escaped = false;

    for (let i = 0; i < text.length; i++) {
        const ch = text[i];

        if (start === -1) {
            if (ch === "{" || ch === "[") {
                start = i;
                depth = 1;
                inString = false;
                escaped = false;
            }
            continue;
        }

        if (inString) {
            if (escaped) {
                escaped = false;
            } else if (ch === "\\") {
                escaped = true;
            } else if (ch === '"') {
                inString = false;
            }
            continue;
        }

        if (ch === '"') {
            inString = true;
        } else if (ch === "{" || ch === "[") {
            depth++;
        } else if (ch === "}" || ch === "]") {
            depth--;

            if (depth === 0) {
                chunks.push(text.slice(start, i + 1));
                start = -1;
            }
        }
    }

    return chunks;
}

// Parse regular JSON, escaped JSON strings, arrays,
// fenced JSON, or multiple concatenated JSON objects.
function parsePayload(payload) {
    if (payload === undefined || payload === null) {
        throw new Error("AI output is empty.");
    }

    if (typeof payload !== "string") {
        return payload;
    }

    let text = payload.trim();

    text = text
        .replace(/^```(?:json)?\s*/i, "")
        .replace(/\s*```$/i, "")
        .trim();

    for (let attempt = 0; attempt < 4; attempt++) {
        try {
            const parsed = JSON.parse(text);

            // Sometimes the AI returns JSON encoded as a string.
            if (typeof parsed === "string") {
                text = parsed.trim();
                continue;
            }

            return parsed;
        } catch (error) {
            const chunks = extractJSONChunks(text);

            if (chunks.length > 0) {
                const parsedChunks = chunks.map(chunk =>
                    JSON.parse(chunk)
                );

                return parsedChunks.length === 1
                    ? parsedChunks[0]
                    : parsedChunks;
            }

            throw new Error(
                "Unable to parse AI output as JSON. Check the input format."
            );
        }
    }

    throw new Error("Too many nested JSON string layers.");
}

// Convert arrays and common wrapper structures into records.
function toRecords(value) {
    if (Array.isArray(value)) {
        return value.flatMap(toRecords);
    }

    if (typeof value === "string") {
        return toRecords(parsePayload(value));
    }

    if (!value || typeof value !== "object") {
        return [];
    }

    for (const key of ["students", "records", "items", "results", "data"]) {
        if (Array.isArray(value[key])) {
            return value[key].flatMap(toRecords);
        }
    }

    // Handle wrappers such as { output: "{...}" }.
    if (value.output !== undefined &&
        value.Student_ID === undefined &&
        value.student_id === undefined) {
        return toRecords(value.output);
    }

    return [value];
}

// Read fields without depending on capitalization.
function getField(record, aliases) {
    const keys = Object.keys(record);

    for (const alias of aliases) {
        const actualKey = keys.find(
            key => key.toLowerCase() === alias.toLowerCase()
        );

        if (actualKey !== undefined) {
            return record[actualKey];
        }
    }

    return undefined;
}

function cleanText(value) {
    return value === undefined || value === null
        ? ""
        : String(value).trim();
}

function parseBoolean(value) {
    if (typeof value === "boolean") {
        return value;
    }

    const normalized = cleanText(value).toLowerCase();

    if (["true", "yes", "y", "1", "paid"].includes(normalized)) {
        return true;
    }

    if (["false", "no", "n", "0", "unpaid"].includes(normalized)) {
        return false;
    }

    return null;
}

function isValidISODate(value) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
        return false;
    }

    const date = new Date(`${value}T00:00:00Z`);

    return (
        !Number.isNaN(date.getTime()) &&
        date.toISOString().slice(0, 10) === value
    );
}

// Clean and validate one student record.
function cleanStudent(record) {
    const studentID = cleanText(
        getField(record, ["Student_ID", "StudentID", "ID"])
    );

    const name = cleanText(getField(record, ["Name", "Student_Name"]));

    const emailOriginal = cleanText(
        getField(record, ["Email", "Email_Address"])
    );

    const emailValid =
        /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailOriginal);

    const email = emailValid ? emailOriginal.toLowerCase() : null;

    const phoneOriginal = cleanText(
        getField(record, ["Phone", "Mobile", "Phone_Number"])
    );

    // Remove spaces and punctuation; also accept an Indian +91 prefix.
    let phoneDigits = phoneOriginal.replace(/\D/g, "");

    if (phoneDigits.length === 12 && phoneDigits.startsWith("91")) {
        phoneDigits = phoneDigits.slice(2);
    }

    const phoneValid = /^\d{10}$/.test(phoneDigits);

    const course = cleanText(getField(record, ["Course"]));
    const city = cleanText(getField(record, ["City"]));

    const feePaid = parseBoolean(
        getField(record, ["Fee_Paid", "FeePaid"])
    );

    const enrolledDateOriginal = cleanText(
        getField(record, ["Enrolled_Date", "Enrollment_Date"])
    );

    const dateValid = isValidISODate(enrolledDateOriginal);

    const errors = [];

    if (!studentID) errors.push("Student_ID is missing");
    if (!name) errors.push("Name is missing");

    if (!emailValid) {
        errors.push(
            emailOriginal ? "Email is invalid" : "Email is missing"
        );
    }

    if (!phoneValid) {
        errors.push(
            phoneOriginal ? "Phone must contain 10 digits" : "Phone is missing"
        );
    }

    if (!course) errors.push("Course is missing");
    if (!city) errors.push("City is missing");

    if (feePaid === null) {
        errors.push("Fee_Paid is missing or invalid");
    }

    if (!dateValid) {
        errors.push("Enrolled_Date must be a valid YYYY-MM-DD date");
    }

    return {
        Student_ID: studentID || null,
        Name: name || null,

        // Invalid emails are not silently replaced with invented addresses.
        Email: email,
        Email_Original: emailOriginal || null,
        Email_Valid: emailValid,

        Phone: phoneValid ? phoneDigits : null,
        Phone_Original: phoneOriginal || null,
        Phone_Valid: phoneValid,

        Course: course || null,
        Fee_Paid: feePaid,
        City: city || null,

        Enrolled_Date: dateValid ? enrolledDateOriginal : null,
        Enrolled_Date_Valid: dateValid,

        Needs_Review: errors.length > 0,
        Validation_Errors: errors
    };
}

// Process every incoming n8n item.
for (let i = 0; i < inputItems.length; i++) {
    const raw = getPayload(inputItems[i]);

    try {
        const parsed = parsePayload(raw);
        const records = toRecords(parsed);

        if (records.length === 0) {
            throw new Error("No student records were found.");
        }

        for (const record of records) {
            if (
                !record ||
                typeof record !== "object" ||
                Array.isArray(record)
            ) {
                outputItems.push({
                    json: {
                        _parseError: true,
                        Source_Item: i,
                        Error: "Expected a student JSON object.",
                        Raw_Record: record
                    }
                });
                continue;
            }

            outputItems.push({
                json: cleanStudent(record)
            });
        }
    } catch (error) {
        outputItems.push({
            json: {
                _parseError: true,
                Source_Item: i,
                Error: error.message,
                Raw_Output: typeof raw === "string"
                    ? raw
                    : JSON.stringify(raw)
            }
        });
    }
}

return outputItems;
